import React, { useState } from 'react';
import './SendMoney.css';

function SendMoney() {
  const myWallets = [
    { id: 1, name: 'Personal Wallet', balance: 5000, currency: 'USD' },
    { id: 2, name: 'Business Wallet', balance: 10000, currency: 'USD' },
    { id: 3, name: 'Savings Wallet', balance: 3000, currency: 'USD' },
  ];

  const recipientWallets = [
    { id: 1, name: 'John Doe', walletId: 'JD123', type: 'Personal' },
    { id: 2, name: 'Jane Smith', walletId: 'JS456', type: 'Business' },
    { id: 3, name: 'Add New Recipient', walletId: 'new', type: 'New' },
  ];

  const [formData, setFormData] = useState({
    sourceWallet: '',
    recipientWallet: '',
    amount: '',
    description: '',
  });

  const [showNewRecipient, setShowNewRecipient] = useState(false);
  const [newRecipient, setNewRecipient] = useState({
    name: '',
    walletId: '',
    type: 'Personal',
  });

  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));

    if (name === 'recipientWallet' && value === 'new') {
      setShowNewRecipient(true);
    } else if (name === 'recipientWallet') {
      setShowNewRecipient(false);
    }

    setError(''); // Clear errors on new input
  };

  const handleNewRecipientChange = (e) => {
    const { name, value } = e.target;
    setNewRecipient((prev) => ({
      ...prev,
      [name]: value,
    }));
    setError('');
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (Number(formData.amount) > walletBalance) {
      setError('Amount exceeds available balance!');
      return;
    }

    const transferDetails = showNewRecipient
      ? { ...formData, newRecipient }
      : formData;

    console.log('Transfer details:', transferDetails);
    alert('Transfer successful!'); // Simulate successful transaction
    setFormData({
      sourceWallet: '',
      recipientWallet: '',
      amount: '',
      description: '',
    });
    setShowNewRecipient(false);
    setNewRecipient({ name: '', walletId: '', type: 'Personal' });
  };

  const selectedWallet = myWallets.find((w) => w.id === Number(formData.sourceWallet));
  const walletBalance = selectedWallet ? selectedWallet.balance : 0;

  return (
    <div className="send-money-page">
      <h2>Send Money</h2>
      <form onSubmit={handleSubmit} className="send-money-form">
        {/* Source Wallet Selection */}
        <div className="form-group">
          <label htmlFor="sourceWallet">From Wallet</label>
          <select
            id="sourceWallet"
            name="sourceWallet"
            value={formData.sourceWallet}
            onChange={handleChange}
            required
          >
            <option value="">Select your wallet</option>
            {myWallets.map((wallet) => (
              <option key={wallet.id} value={wallet.id}>
                {wallet.name} - Balance: ${wallet.balance.toLocaleString()} {wallet.currency}
              </option>
            ))}
          </select>
          {formData.sourceWallet && (
            <div className="wallet-balance">
              Available Balance: ${walletBalance.toLocaleString()} {selectedWallet?.currency}
            </div>
          )}
        </div>

        {/* Recipient Wallet Selection */}
        <div className="form-group">
          <label htmlFor="recipientWallet">To Wallet</label>
          <select
            id="recipientWallet"
            name="recipientWallet"
            value={formData.recipientWallet}
            onChange={handleChange}
            required
          >
            <option value="">Select recipient</option>
            {recipientWallets.map((wallet) => (
              <option key={wallet.id} value={wallet.walletId}>
                {wallet.name} {wallet.walletId !== 'new' && `(${wallet.walletId})`}
              </option>
            ))}
          </select>
        </div>

        {/* New Recipient Form */}
        {showNewRecipient && (
          <div className="new-recipient-form">
            <h3>New Recipient Details</h3>
            <div className="form-group">
              <label htmlFor="recipientName">Recipient Name</label>
              <input
                type="text"
                id="recipientName"
                name="name"
                value={newRecipient.name}
                onChange={handleNewRecipientChange}
                placeholder="Enter recipient's name"
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="recipientWalletId">Wallet ID</label>
              <input
                type="text"
                id="recipientWalletId"
                name="walletId"
                value={newRecipient.walletId}
                onChange={handleNewRecipientChange}
                placeholder="Enter wallet ID"
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="recipientType">Wallet Type</label>
              <select
                id="recipientType"
                name="type"
                value={newRecipient.type}
                onChange={handleNewRecipientChange}
                required
              >
                <option value="Personal">Personal</option>
                <option value="Business">Business</option>
              </select>
            </div>
          </div>
        )}

        {/* Amount and Description */}
        <div className="form-group">
          <label htmlFor="amount">Amount</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={formData.amount}
            onChange={handleChange}
            placeholder="Enter amount"
            min="1"
            max={walletBalance}
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="description">Description</label>
          <input
            type="text"
            id="description"
            name="description"
            value={formData.description}
            onChange={handleChange}
            placeholder="Enter description (optional)"
          />
        </div>

        {error && <div className="error-message">{error}</div>}

        <button
          type="submit"
          className="submit-button"
          disabled={
            !formData.sourceWallet ||
            !formData.recipientWallet ||
            !formData.amount ||
            Number(formData.amount) > walletBalance
          }
        >
          Send Money
        </button>
      </form>
    </div>
  );
}

export default SendMoney;
